$$

which with

\begin{equation*}
A_{i j}=\sum_{p=1}^{N} q_{i}^{p} q_{j}^{p} \quad \text { and } \quad b_{j}=\sum_{p=1}^{N} t^{p} q_{j}^{p} \tag{9.12}
